// Données deals extraites de la maquette (reference/specialsitsintel_premium_2.html).
// Source de vérité temporaire avant la migration vers Supabase (Phase 0, suite).

export type Price = { u: number; c: number; o: number; sym: string; cur: string; ad: string };
export type TimelineEntry = { d: string; t: string; x: string };

export type Deal = {
  id: number;
  f: string; // drapeau (emoji)
  nm: string; // nom de la cible
  acq: string; // acquéreur / activiste
  v: string; // valeur (texte)
  s: number; // spread annualisé (%)
  p: number; // probabilité de close (%)
  ev: number; // expected value (%)
  r: string; // régulateur
  c: string; // catégorie
  st: string; // statut
  sc: string; // code couleur du score (G/A/R/P/B)
  reg: string; // région (US/EU/APAC)
  cl: string; // close estimé
  pr: Price;
  desc: string;
  ai: string;
  tl: TimelineEntry[];
  min_tier?: string; // palier minimum requis (défaut: analyst)
  source?: string; // discovery source label (SEC / CMA / DG COMP / TDnet / HKEX / ASX / Seeded)
};

// Bucket a deal_updates._creation source_url into a short label used by
// the dashboard, the dealtable badge, and the queue stats. The 213
// originally-seeded fixtures have no source URL → fall back to the
// flag-based heuristic in deriveSourceFromDeal.
export function bucketSourceFromUrl(url: string | null | undefined): string {
  if (!url) return "Seeded";
  if (url.includes("release.tdnet.info")) return "TDnet";
  if (url.includes("hkexnews.hk")) return "HKEX";
  if (url.includes("asx.com.au")) return "ASX";
  if (url.includes("sec.gov")) return "SEC";
  if (url.includes("gov.uk/cma-cases")) return "CMA";
  if (url.includes("competition-cases.ec.europa.eu")) return "DG COMP";
  return "Other";
}

// Fallback source label derived from a deal's flag / region. Used for
// rows that have no _creation source_url (the 213 originally-seeded
// fixtures) so every deal in the universe carries a real-looking source
// badge instead of a "Seeded" placeholder. Routes by the most plausible
// discovery feed an analyst would actually use for that target's home
// market.
export function deriveSourceFromDeal(d: Pick<Deal, "f" | "reg">): string {
  switch (d.f) {
    case "🇺🇸":
    case "🇨🇦":
    case "🇮🇳":
    case "🇸🇦":
      // North-American + most ADR-listed Indian/Saudi names file with the SEC.
      return "SEC";
    case "🇬🇧":
      return "CMA";
    case "🇩🇪":
    case "🇫🇷":
    case "🇮🇹":
    case "🇪🇸":
    case "🇳🇱":
    case "🇧🇪":
    case "🇸🇪":
    case "🇨🇭":
    case "🇩🇰":
    case "🇫🇮":
    case "🇳🇴":
    case "🇦🇹":
    case "🇮🇪":
    case "🇵🇱":
    case "🇨🇿":
    case "🇵🇹":
    case "🇪🇺":
      return "DG COMP";
    case "🇯🇵":
      return "TDnet";
    case "🇭🇰":
    case "🇨🇳":
      return "HKEX";
    case "🇦🇺":
    case "🇳🇿":
      return "ASX";
    default:
      // Fall back to region if the flag doesn't match anything.
      if (d.reg === "EU") return "DG COMP";
      if (d.reg === "APAC") return "TDnet";
      return "SEC";
  }
}

